# owner: platform
"""Lay students out in rows of seats, sorted by surname."""

from typing import Iterable, List

from rosterkit.models import Student


def _sort_key(student: Student):
    last = student.last_name.casefold()
    return (last, student.first_name.casefold())


def _row_line(number: int, members: List[Student]) -> str:
    names = " | ".join(item.display_name for item in members)
    return f"Row {number}: {names}"


# ---
def seating_rows(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One text line per row, filled in surname order."""
    pupils = sorted(students, key=_sort_key)
    if seats_per_row <= 0:
        raise ValueError("seats_per_row must be positive")
    if not pupils:
        raise ValueError("no students to seat")
    step = seats_per_row
    return [
        _row_line(start // step + 1, pupils[start:start + step])
        for start in range(0, len(pupils), step)
    ]

