# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student


def make_student(last, first):
    return Student(last + first, last, first, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.pupils = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Albright", "Cass"),
        ]

    def test_sorted_by_last_name_in_rows(self):
        rows = seating_rows(self.pupils, 2)
        self.assertEqual(rows, [
            "Row 1: Albright, Cass | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ])

    def test_single_row_when_seats_exceed_students(self):
        rows = seating_rows(self.pupils, 10)
        self.assertEqual(len(rows), 1)

    def test_first_name_breaks_ties(self):
        pupils = [
            make_student("Reyes", "Zoe"),
            make_student("Reyes", "Alma")
        ]
        rows = seating_rows(pupils, 2)
        self.assertEqual(
            rows, ["Row 1: Reyes, Alma | Reyes, Zoe"]
        )

    def test_sort_ignores_case(self):
        pupils = [
            make_student("zane", "Ann"),
            make_student("Young", "Bo")
        ]
        rows = seating_rows(pupils, 1)
        self.assertTrue(rows[0].startswith("Row 1: Young"))

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.pupils, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.pupils, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
